begin;

alter table public.marketplace_settlement_legs drop constraint marketplace_settlement_leg_type_check;
alter table public.marketplace_settlement_legs drop constraint marketplace_settlement_leg_beneficiary_check;
alter table public.marketplace_settlement_legs add constraint marketplace_settlement_leg_type_check check(leg_type in('seller_net','creator_commission','platform_fee','influencer_commission'));
alter table public.marketplace_settlement_legs add constraint marketplace_settlement_leg_beneficiary_check check((leg_type='seller_net'and beneficiary_user_id is not null)or(leg_type='creator_commission'and beneficiary_user_id is not null)or(leg_type='platform_fee'and beneficiary_user_id is null)or leg_type='influencer_commission');

create or replace function public.marketplace_allocation_release_guard()returns trigger language plpgsql set search_path=public as $$begin if current_setting('app.marketplace_settlement',true)='on'and old.status='held'and new.status='released'and(old.id,old.payment_id,old.checkout_id,old.order_id,old.seller_id,old.store_id,old.currency,old.gross_amount,old.platform_fee_amount,old.seller_net_amount,old.fee_bps,old.creator_user_id,old.creator_commission_amount)is not distinct from(new.id,new.payment_id,new.checkout_id,new.order_id,new.seller_id,new.store_id,new.currency,new.gross_amount,new.platform_fee_amount,new.seller_net_amount,new.fee_bps,new.creator_user_id,new.creator_commission_amount)and new.released_at is not null and new.refunded_at is null then return new;end if;raise exception using errcode='42501',message='marketplace_payment_snapshot_immutable';end$$;

create or replace function public.marketplace_order_settlement_receipt(p_settlement_id uuid,p_role text)returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('settlement',jsonb_build_object('id',s.id,'status',s.status,'order_id',s.order_id,'currency',s.currency,'gross_amount',s.gross_amount,'seller_net_amount',case when p_role='seller'then s.seller_net_amount end,'creator_commission_amount',case when p_role='seller'then s.creator_commission_amount end,'platform_fee_amount',case when p_role='seller'then s.platform_fee_amount end,'confirmed_at',s.confirmed_at,'released_at',s.released_at),'order',jsonb_build_object('id',o.id,'status',o.status,'delivered_at',o.delivered_at),'shipment',jsonb_build_object('status',sh.status,'delivered_at',sh.delivered_at),'allocation',jsonb_build_object('status',a.status,'released_at',a.released_at),'seller',case when p_role='seller'then jsonb_build_object('new_bdag_balance',(select balance from public.ledger_accounts where owner_id=s.seller_id and account_type='user'and currency='BDAG'))end)from public.marketplace_order_settlements s join public.marketplace_orders o on o.id=s.order_id join public.marketplace_order_shipments sh on sh.order_id=o.id join public.marketplace_payment_allocations a on a.id=s.allocation_id where s.id=p_settlement_id and p_role in('buyer','seller')$$;

create or replace function public.confirm_marketplace_order_delivery_and_release(p_buyer_id uuid,p_order_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=public as $$
declare o public.marketplace_orders;sh public.marketplace_order_shipments;p public.marketplace_payments;a public.marketplace_payment_allocations;s public.marketplace_order_settlements;v_fingerprint text;v_settlement uuid:=gen_random_uuid();v_escrow uuid;v_seller_account uuid;v_creator_account uuid;v_platform_account uuid;v_seller_tx uuid;v_creator_tx uuid;v_platform_tx uuid;v_now timestamptz:=now();v_escrow_balance numeric;
begin
 if p_buyer_id is null or p_order_id is null or p_idempotency_key is null then raise exception using errcode='22023',message='marketplace_delivery_invalid_input';end if;
 v_fingerprint:=encode(extensions.digest('marketplace_order_confirm_delivery:'||p_order_id::text,'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended(p_buyer_id::text||':marketplace-delivery:'||p_idempotency_key::text,0));perform pg_advisory_xact_lock(hashtextextended('marketplace-order-settlement:'||p_order_id::text,0));
 select*into o from public.marketplace_orders where id=p_order_id for update;if not found then raise exception using errcode='P0002',message='marketplace_order_not_found';end if;if o.buyer_id<>p_buyer_id then raise exception using errcode='42501',message='marketplace_order_not_owned';end if;
 select*into s from public.marketplace_order_settlements where buyer_id=p_buyer_id and idempotency_key=p_idempotency_key;if found then if s.order_id<>p_order_id or s.request_fingerprint<>v_fingerprint then raise exception using errcode='23505',message='marketplace_settlement_idempotency_conflict';end if;return public.marketplace_order_settlement_receipt(s.id,'buyer');end if;select*into s from public.marketplace_order_settlements where order_id=p_order_id;if found then return public.marketplace_order_settlement_receipt(s.id,'buyer');end if;
 select*into sh from public.marketplace_order_shipments where order_id=o.id for update;select mp.*into p from public.marketplace_payments mp join public.marketplace_checkout_sessions c on c.id=mp.checkout_id where mp.checkout_id=o.checkout_id and c.status='paid'for update of mp;select*into a from public.marketplace_payment_allocations where order_id=o.id for update;
 if p.id is null or p.status<>'paid'then raise exception using message='marketplace_order_not_paid';end if;if o.status<>'shipped'then raise exception using message='marketplace_order_not_shipped';end if;if sh.id is null or sh.status<>'shipped'then raise exception using message='marketplace_shipment_not_shipped';end if;if a.id is null or a.status<>'held'then raise exception using message='marketplace_allocation_not_held';end if;
 if a.payment_id<>p.id or a.checkout_id<>o.checkout_id or a.seller_id<>o.seller_id or a.store_id<>o.store_id or a.currency<>'BDAG'or o.currency<>'BDAG'or a.gross_amount<>o.total or a.gross_amount<>a.seller_net_amount+a.creator_commission_amount+a.platform_fee_amount or(a.creator_commission_amount=0)<>(a.creator_user_id is null)then raise exception using message='marketplace_settlement_integrity_error';end if;
 v_escrow:=public.ensure_marketplace_escrow_account();v_seller_account:=public.ensure_ledger_account(o.seller_id);v_platform_account:=public.ensure_marketplace_platform_account();if a.creator_commission_amount>0 then v_creator_account:=public.ensure_ledger_account(a.creator_user_id);end if;
 perform 1 from public.ledger_accounts where id=any(array_remove(array[v_escrow,v_seller_account,v_creator_account,v_platform_account],null))order by id for update;select balance into v_escrow_balance from public.ledger_accounts where id=v_escrow and currency='BDAG'and not frozen;if v_escrow_balance is null or v_escrow_balance<a.gross_amount then raise exception using message='marketplace_escrow_insufficient_balance';end if;if exists(select 1 from public.ledger_accounts where id=any(array_remove(array[v_seller_account,v_creator_account,v_platform_account],null))and(currency<>'BDAG'or frozen))then raise exception using message='marketplace_settlement_integrity_error';end if;
 insert into public.marketplace_order_settlements(id,payment_id,allocation_id,checkout_id,order_id,buyer_id,seller_id,store_id,gross_amount,seller_net_amount,creator_user_id,creator_commission_amount,platform_fee_amount,confirmed_by,idempotency_key,request_fingerprint,confirmed_at,released_at)values(v_settlement,p.id,a.id,o.checkout_id,o.id,o.buyer_id,o.seller_id,o.store_id,a.gross_amount,a.seller_net_amount,a.creator_user_id,a.creator_commission_amount,a.platform_fee_amount,p_buyer_id,p_idempotency_key,v_fingerprint,v_now,v_now);
 if a.seller_net_amount>0 then v_seller_tx:=gen_random_uuid();insert into public.financial_transactions(id,from_account_id,to_account_id,operation_type,amount,fee_amount,currency,status,reference_type,reference_id,idempotency_key,initiated_by)values(v_seller_tx,v_escrow,v_seller_account,'marketplace_seller_settlement',a.seller_net_amount,0,'BDAG','completed','marketplace_order',o.id::text,v_settlement::text||':seller',p_buyer_id);perform public.ledger_debit(v_seller_tx,v_escrow,a.seller_net_amount,'Marketplace seller settlement',jsonb_build_object('fin_txn_id',v_seller_tx,'order_id',o.id));perform public.ledger_credit(v_seller_tx,v_seller_account,a.seller_net_amount,'Marketplace seller settlement',jsonb_build_object('fin_txn_id',v_seller_tx,'order_id',o.id));end if;insert into public.marketplace_settlement_legs(settlement_id,leg_key,leg_type,beneficiary_user_id,destination_account_id,amount,financial_transaction_id)values(v_settlement,'seller_net','seller_net',o.seller_id,v_seller_account,a.seller_net_amount,v_seller_tx);
 if a.creator_commission_amount>0 then v_creator_tx:=gen_random_uuid();insert into public.financial_transactions(id,from_account_id,to_account_id,operation_type,amount,fee_amount,currency,status,reference_type,reference_id,idempotency_key,initiated_by)values(v_creator_tx,v_escrow,v_creator_account,'marketplace_creator_commission_settlement',a.creator_commission_amount,0,'BDAG','completed','marketplace_order',o.id::text,v_settlement::text||':creator',p_buyer_id);perform public.ledger_debit(v_creator_tx,v_escrow,a.creator_commission_amount,'Marketplace creator commission settlement',jsonb_build_object('fin_txn_id',v_creator_tx,'order_id',o.id));perform public.ledger_credit(v_creator_tx,v_creator_account,a.creator_commission_amount,'Marketplace creator commission settlement',jsonb_build_object('fin_txn_id',v_creator_tx,'order_id',o.id));insert into public.marketplace_settlement_legs(settlement_id,leg_key,leg_type,beneficiary_user_id,destination_account_id,amount,financial_transaction_id)values(v_settlement,'creator_commission','creator_commission',a.creator_user_id,v_creator_account,a.creator_commission_amount,v_creator_tx);end if;
 if a.platform_fee_amount>0 then v_platform_tx:=gen_random_uuid();insert into public.financial_transactions(id,from_account_id,to_account_id,operation_type,amount,fee_amount,currency,status,reference_type,reference_id,idempotency_key,initiated_by)values(v_platform_tx,v_escrow,v_platform_account,'marketplace_platform_fee_settlement',a.platform_fee_amount,0,'BDAG','completed','marketplace_order',o.id::text,v_settlement::text||':platform',p_buyer_id);perform public.ledger_debit(v_platform_tx,v_escrow,a.platform_fee_amount,'Marketplace platform fee settlement',jsonb_build_object('fin_txn_id',v_platform_tx,'order_id',o.id));perform public.ledger_credit(v_platform_tx,v_platform_account,a.platform_fee_amount,'Marketplace platform fee settlement',jsonb_build_object('fin_txn_id',v_platform_tx,'order_id',o.id));end if;insert into public.marketplace_settlement_legs(settlement_id,leg_key,leg_type,beneficiary_user_id,destination_account_id,amount,financial_transaction_id)values(v_settlement,'platform_fee','platform_fee',null,v_platform_account,a.platform_fee_amount,v_platform_tx);
 perform set_config('app.marketplace_settlement','on',true);update public.marketplace_payment_allocations set status='released',released_at=v_now where id=a.id and status='held';update public.marketplace_orders set status='delivered',delivered_at=v_now,fulfillment_updated_at=v_now,fulfillment_version=fulfillment_version+1 where id=o.id and status='shipped';update public.marketplace_order_shipments set status='delivered',delivered_at=v_now where id=sh.id and status='shipped';
 insert into public.marketplace_order_events(order_id,checkout_id,buyer_id,seller_id,store_id,event_type,from_status,to_status,actor_id,actor_role,idempotency_key,metadata,created_at)values(o.id,o.checkout_id,o.buyer_id,o.seller_id,o.store_id,'delivery_confirmed','shipped','delivered',p_buyer_id,'buyer',p_idempotency_key,jsonb_build_object('settlement_id',v_settlement,'currency','BDAG'),v_now),(o.id,o.checkout_id,o.buyer_id,o.seller_id,o.store_id,'escrow_released','delivered','delivered',p_buyer_id,'buyer',p_idempotency_key,jsonb_build_object('settlement_id',v_settlement,'currency','BDAG','status','released'),v_now);return public.marketplace_order_settlement_receipt(v_settlement,'buyer');
end$$;

create or replace function public.reconcile_marketplace_live_commissions()returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('allocation_split_mismatch',(select count(*)from public.marketplace_payment_allocations where gross_amount is distinct from seller_net_amount+platform_fee_amount+creator_commission_amount),'own_product_commission_mismatch',(select count(*)from public.marketplace_live_commission_sources s join public.marketplace_payment_allocations a on a.id=s.allocation_id where s.commerce_mode='own_product'and(a.creator_commission_amount<>0 or a.creator_user_id is not null)),'affiliate_commission_mismatch',(select count(*)from public.marketplace_live_commission_sources s join public.marketplace_payment_allocations a on a.id=s.allocation_id where s.commerce_mode='affiliate_product'and(a.creator_user_id is distinct from s.host_id or a.creator_commission_amount is distinct from s.creator_commission_amount or a.creator_commission_amount<=0)),'source_allocation_mismatch',(select count(*)from public.marketplace_live_commission_sources s join public.marketplace_payment_allocations a on a.id=s.allocation_id where(s.checkout_id,s.order_id,s.payment_id,s.seller_id,s.store_id,s.currency,s.creator_commission_amount)is distinct from(a.checkout_id,a.order_id,a.payment_id,a.seller_id,a.store_id,a.currency,a.creator_commission_amount)),'missing_creator_leg',(select count(*)from public.marketplace_order_settlements s where s.creator_commission_amount>0 and not exists(select 1 from public.marketplace_settlement_legs l where l.settlement_id=s.id and l.leg_type='creator_commission')),'duplicate_creator_leg',(select count(*)from(select settlement_id from public.marketplace_settlement_legs where leg_type='creator_commission'group by 1 having count(*)>1)x),'unexpected_creator_leg',(select count(*)from public.marketplace_order_settlements s join public.marketplace_settlement_legs l on l.settlement_id=s.id and l.leg_type='creator_commission'where s.creator_commission_amount=0),'creator_transaction_mismatch',(select count(*)from public.marketplace_order_settlements s join public.marketplace_settlement_legs l on l.settlement_id=s.id and l.leg_type='creator_commission'left join public.financial_transactions f on f.id=l.financial_transaction_id where(l.amount,l.beneficiary_user_id,f.operation_type,f.amount,f.currency,f.status,f.reference_type,f.reference_id,f.initiated_by)is distinct from(s.creator_commission_amount,s.creator_user_id,'marketplace_creator_commission_settlement',s.creator_commission_amount,'BDAG','completed','marketplace_order',s.order_id::text,s.buyer_id)),'creator_credit_before_delivery',(select count(*)from public.marketplace_payment_allocations a join public.marketplace_live_commission_sources src on src.allocation_id=a.id join public.financial_transactions f on f.reference_type='marketplace_order'and f.reference_id=a.order_id::text and f.operation_type='marketplace_creator_commission_settlement'where a.status='held'))$$;

revoke all on function public.reconcile_marketplace_live_commissions()from public,anon,authenticated;
grant execute on function public.reconcile_marketplace_live_commissions()to service_role;

commit;
